const news = $('상위 1건만').first().json;
const pageRes = $input.first().json;

const rawTitle = news.title || '(제목 없음)';
const link = news.link || '';
const source = (news.source && news.source.title) ? news.source.title : (news.creator || '연합뉴스');
const pubDate = news.pubDate || news.isoDate || '';

let title = rawTitle;
if (source && title.endsWith(` - ${source}`)) {
  title = title.slice(0, -(source.length + 3)).trim();
}

// 기사 원문 HTML에서 og:image 추출 (기본 로고/아이콘은 제외)
const html_source = (typeof pageRes === 'string') ? pageRes : (pageRes.data || pageRes.body || '');
let imageUrl = '';
if (html_source) {
  const m = html_source.match(/<meta[^>]+property=["']og:image["'][^>]*content=["']([^"']+)["']/i)
    || html_source.match(/<meta[^>]+content=["']([^"']+)["'][^>]*property=["']og:image["']/i);
  if (m) {
    const candidate = m[1];
    const isDefaultLogo = /yonhapnews_logo/i.test(candidate);
    if (!isDefaultLogo) imageUrl = candidate;
  }
}

let publishedText = '';
if (pubDate) {
  const d = new Date(pubDate);
  if (!isNaN(d.getTime())) {
    publishedText = d.toLocaleString('ko-KR', { timeZone: 'Asia/Seoul', dateStyle: 'medium', timeStyle: 'short' });
  }
}

const today = new Date().toLocaleDateString('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' });

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const subject = `📰 오늘의 주요 뉴스 - ${title}`;
const metaParts = [source, publishedText].filter(Boolean).join(' · ');

const imageHtml = imageUrl
  ? `<img src="${escapeHtml(imageUrl)}" alt="기사 이미지" style="width:100%;max-height:320px;object-fit:cover;border-radius:8px;margin:0 0 20px;display:block;">`
  : '';

const html = `<!DOCTYPE html>
<html lang="ko">
<body style="margin:0;padding:24px;background:#f5f6f8;font-family:'Malgun Gothic',AppleSDGothicNeo-Regular,sans-serif;">
  <div style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:12px;padding:32px;">
    <p style="margin:0 0 8px;color:#6b7280;font-size:13px;">${escapeHtml(today)}</p>
    <h1 style="margin:0 0 20px;font-size:20px;line-height:1.4;color:#111827;">📰 오늘의 주요 뉴스</h1>
    ${imageHtml}
    <h2 style="margin:0 0 12px;font-size:17px;line-height:1.5;color:#1f2937;">${escapeHtml(title)}</h2>
    ${metaParts ? `<p style="margin:0 0 20px;color:#6b7280;font-size:13px;">${escapeHtml(metaParts)}</p>` : ''}
    <a href="${escapeHtml(link)}" style="display:inline-block;padding:11px 20px;background:#2563eb;color:#ffffff;text-decoration:none;border-radius:8px;font-size:14px;">기사 전문 보기</a>
    <p style="margin:28px 0 0;padding-top:16px;border-top:1px solid #e5e7eb;color:#9ca3af;font-size:12px;">n8n 자동 발송 · 연합뉴스 최신기사</p>
  </div>
</body>
</html>`;

const text = [
  `📰 오늘의 주요 뉴스 (${today})`,
  '',
  title,
  metaParts,
  '',
  link
].filter(Boolean).join('\n');

return [{ json: { subject, html, text, title, link, imageUrl } }];
